#include <memory>
#include <iostream>

struct Data { int value = 42; };

void transfer_ownership(std::auto_ptr<Data> p) {
    // p now owns the data. Original caller's pointer is null.
    std::cout << "Inside func: " << p->value << std::endl;
}

int main() {
    std::auto_ptr<Data> original(new Data);

    // 1. Destructive Copy/Transfer
    transfer_ownership(original); 
    // original is now NULL.
    // if (original.get() == nullptr) { std::cout << "Original is null.\n"; }

    // 2. Attempted Shared Ownership (DANGER!)
